        } elseif ((is_numeric($token)) || ($token === null) || (is_bool($token)) || ($token == '') || ($token[0] == self::FORMULA_STRING_QUOTE) || ($token[0] == '#')) {
            $stack->push($tokenData['type'], $token, $tokenData['reference']);
            if (isset($storeKey)) {
